-- >>> 0015_adminish_rls.sql >>>
-- Broaden owner-only policies to allow Admin as well (adminish).
-- Replaces owner_can_* policies on items, kits, and settings with admin_can_* using
-- public.app_current_tenant_id() and public.app_is_admin() helpers (SECURITY DEFINER).

do $$
begin
  -- ITEMS
  execute 'drop policy if exists owner_can_insert_items on public.items';
  execute 'drop policy if exists owner_can_update_items on public.items';
  execute 'drop policy if exists owner_can_delete_items on public.items';
  execute 'drop policy if exists admin_can_insert_items on public.items';
  execute 'drop policy if exists admin_can_update_items on public.items';
  execute 'drop policy if exists admin_can_delete_items on public.items';

  execute 'create policy admin_can_insert_items on public.items for insert with check (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_update_items on public.items for update using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_delete_items on public.items for delete using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';

  -- KITS
  execute 'drop policy if exists owner_can_insert_kits on public.kits';
  execute 'drop policy if exists owner_can_update_kits on public.kits';
  execute 'drop policy if exists owner_can_delete_kits on public.kits';
  execute 'drop policy if exists admin_can_insert_kits on public.kits';
  execute 'drop policy if exists admin_can_update_kits on public.kits';
  execute 'drop policy if exists admin_can_delete_kits on public.kits';

  execute 'create policy admin_can_insert_kits on public.kits for insert with check (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_update_kits on public.kits for update using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_delete_kits on public.kits for delete using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';

  -- SETTINGS
  execute 'drop policy if exists owner_can_insert_settings on public.settings';
  execute 'drop policy if exists owner_can_update_settings on public.settings';
  execute 'drop policy if exists owner_can_delete_settings on public.settings';
  execute 'drop policy if exists admin_can_insert_settings on public.settings';
  execute 'drop policy if exists admin_can_update_settings on public.settings';
  execute 'drop policy if exists admin_can_delete_settings on public.settings';

  execute 'create policy admin_can_insert_settings on public.settings for insert with check (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_update_settings on public.settings for update using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
  execute 'create policy admin_can_delete_settings on public.settings for delete using (
    tenant_id = public.app_current_tenant_id() and public.app_is_admin()
  )';
end $$;


-- <<< 0015_adminish_rls.sql <<<


-- >>> 0016_bootstrap_profile_on_signup.sql >>>
-- Auto-provision tenant + profile for new auth users to avoid "Profile not ready" UX.
-- Idempotent: recreate function and trigger safely.

create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_tenant uuid;
  v_name text;
begin
  -- If a profile already exists for this user, do nothing
  if exists (select 1 from public.profiles where user_id = new.id) then
    return new;
  end if;

  -- Derive a friendly name from email if available
  v_name := coalesce(new.raw_user_meta_data->>'name', new.email, 'User');

  -- Create a tenant and owner profile for this user
  insert into public.tenants(name) values (coalesce(v_name, 'Company'))
    returning id into v_tenant;

  insert into public.profiles(user_id, tenant_id, role, display_name)
    values (new.id, v_tenant, 'owner', v_name);

  -- Seed default settings for the new tenant if not present
  insert into public.settings(tenant_id, currency, default_tax_rate, deposit_percent)
    values (v_tenant, 'INR', 0, 0)
    on conflict do nothing;

  return new;
end;
$$;

-- Create trigger on auth.users to call the bootstrapper
drop trigger if exists trg_handle_new_auth_user on auth.users;
create trigger trg_handle_new_auth_user
  after insert on auth.users
  for each row
  execute function public.handle_new_auth_user();

-- Hardening: prevent direct execution; only the trigger should invoke this.
revoke all on function public.handle_new_auth_user() from public;
revoke all on function public.handle_new_auth_user() from anon;
revoke all on function public.handle_new_auth_user() from authenticated;

-- <<< 0016_bootstrap_profile_on_signup.sql <<<


-- >>> 0017_bootstrap_only_first_user.sql >>>
-- Modify bootstrap to only auto-provision for the first-ever user/tenant.
-- Prevents accidental tenant sprawl when normal team members sign in with Gmail.

create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_tenant uuid;
  v_name text;
  v_has_any boolean;
begin
  -- If a profile already exists for this user, do nothing
  if exists (select 1 from public.profiles where user_id = new.id) then
    return new;
  end if;

  -- Only bootstrap when there are no tenants yet (first user wins)
  select exists(select 1 from public.tenants) into v_has_any;
  if v_has_any then
    -- Do not auto-create a tenant; wait for admin invite to assign profile
    return new;
  end if;

  v_name := coalesce(new.raw_user_meta_data->>'name', new.email, 'Owner');
  insert into public.tenants(name) values (coalesce(v_name, 'Company'))
    returning id into v_tenant;
  insert into public.profiles(user_id, tenant_id, role, display_name)
    values (new.id, v_tenant, 'owner', v_name);
  insert into public.settings(tenant_id, currency, default_tax_rate, deposit_percent)
    values (v_tenant, 'INR', 0, 0)
    on conflict do nothing;
  return new;
end;
$$;


-- <<< 0017_bootstrap_only_first_user.sql <<<


-- >>> 0018_role_enum_extend.sql >>>
-- Ensure the role enum contains all app roles used by the UI.
-- Safe, idempotent adds per label.
do $$ begin
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'admin'
  ) then
    alter type role add value 'admin';
  end if;
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'manager'
  ) then
    alter type role add value 'manager';
  end if;
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'sales'
  ) then
    alter type role add value 'sales';
  end if;
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'technician'
  ) then
    alter type role add value 'technician';
  end if;
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'accountant'
  ) then
    alter type role add value 'accountant';
  end if;
  if not exists (
    select 1 from pg_type t
    join pg_enum e on e.enumtypid = t.oid
    where t.typname = 'role' and e.enumlabel = 'viewer'
  ) then
    alter type role add value 'viewer';
  end if;
  -- 'staff' already exists in initial enum; keep for backward compatibility.
end $$;


