-- >>> 0021_customers_soft_delete_rls.sql >>>
-- Exclude soft-deleted customers from normal SELECT via RLS.
do $$
begin
  -- Drop generic tenant select policy if present
  if exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'customers' and policyname = 'tenant_can_select_customers'
  ) then
    execute 'drop policy tenant_can_select_customers on public.customers';
  end if;
  -- Create refined policy that omits deleted rows
  execute 'create policy tenant_can_select_customers on public.customers for select using (
    tenant_id = public.app_current_tenant_id() and deleted_at is null
  )';
end $$;


-- <<< 0021_customers_soft_delete_rls.sql <<<


-- >>> 0022_enforce_last_owner_guard.sql >>>
-- Prevent removing the last owner of a tenant.
create or replace function public.enforce_at_least_one_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant uuid;
  v_remaining integer;
begin
  if TG_OP = 'DELETE' then
    v_tenant := old.tenant_id;
    if old.role = 'owner' then
      select count(*) into v_remaining from public.profiles
      where tenant_id = v_tenant and user_id <> old.user_id and role = 'owner';
      if coalesce(v_remaining,0) = 0 then
        raise exception 'Cannot remove the last owner from tenant %', v_tenant;
      end if;
    end if;
    return old;
  elsif TG_OP = 'UPDATE' then
    v_tenant := new.tenant_id;
    if old.role = 'owner' and new.role <> 'owner' then
      select count(*) into v_remaining from public.profiles
      where tenant_id = v_tenant and user_id <> old.user_id and role = 'owner';
      if coalesce(v_remaining,0) = 0 then
        raise exception 'Tenant % must retain at least one owner', v_tenant;
      end if;
    end if;
    return new;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_enforce_last_owner on public.profiles;
create trigger trg_enforce_last_owner
before update or delete on public.profiles
for each row execute function public.enforce_at_least_one_owner();


-- <<< 0022_enforce_last_owner_guard.sql <<<

COMMIT;
